/*
 * prog41_series_sum.c
 *
 * Re‑implementation of the original program whose behaviour was
 * observed in the binary “prog41_series_sum”.
 *
 * The program expects exactly two command‑line arguments:
 *
 *   argv[1] – an integer selecting the series (1, 2 or 3)
 *   argv[2] – the number of terms to use (non‑negative, ≤ 100000)
 *
 * Behaviour
 * ----------
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *   * If either argument is not a pure decimal integer → prints "BAD_INPUT".
 *   * If the second argument is negative → prints "BAD_INPUT".
 *   * If the second argument is larger than 100000 → prints "OUT_OF_RANGE".
 *   * If the first argument is not 1, 2 or 3 → prints "BAD_MODE".
 *
 *   Otherwise the program computes a series sum and prints the result
 *   with six digits after the decimal point.
 *
 *   series 1 (argv[1] == 1) :  Σ_{i=1}^{m} 1/(i*i)          (Basel series)
 *   series 2 (argv[1] == 2) :  Σ_{i=1}^{m} 1/i                (harmonic series)
 *   series 3 (argv[1] == 3) :  1 + Σ_{i=1}^{m} 1/i!            (e‑approximation)
 *
 *   For series 3 the initial term 1 (i = 0) is always included, so with
 *   m == 0 the result is exactly 1.0.
 *
 * All messages are printed with a trailing newline, exactly as the
 * original binary used `puts`.  The result is printed with `printf("%.6f\n", …)`.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     *  Argument count check
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Parse the two arguments, checking that the whole strings are
     *  consumed by strtol.
     * ----------------------------------------------------------------- */
    char *end1, *end2;
    long series = strtol(argv[1], &end1, 10);
    long terms  = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Basic validation of the second argument
     * ----------------------------------------------------------------- */
    if (terms < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (terms > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Choose the series
     * ----------------------------------------------------------------- */
    double sum = 0.0;

    switch (series) {
        case 1:   /* Σ 1/(i*i) */
            for (long i = 1; i <= terms; ++i) {
                sum += 1.0 / ((double)i * (double)i);
            }
            break;

        case 2:   /* Σ 1/i */
            for (long i = 1; i <= terms; ++i) {
                sum += 1.0 / (double)i;
            }
            break;

        case 3:   /* 1 + Σ 1/i! */
            sum = 1.0;               /* the i = 0 term */
            {
                double term = 1.0;   /* current 1/i! */
                for (long i = 1; i <= terms; ++i) {
                    term /= (double)i;   /* term becomes 1/i! */
                    sum  += term;
                }
            }
            break;

        default:
            puts("BAD_MODE");
            return 0;
    }

    /* -----------------------------------------------------------------
     *  Output the result
     * ----------------------------------------------------------------- */
    printf("%.6f\n", sum);
    return 0;
}
